"""Native pasteboard snapshots; inspect privacy markers before any payload read."""
import time
import AppKit
import Quartz
from PySide6.QtCore import QObject, Signal, QTimer, QMimeData, QUrl, QBuffer, QByteArray, QIODevice
from PySide6.QtGui import QImage, QImageReader

from macos_dispatch import on_main
from macos_system import accessibility_allowed

SECRET_MARKERS = ("org.nspasteboard.concealedtype", "org.nspasteboard.transienttype",
                  "org.nspasteboard.autogeneratedtype", "com.agilebits.onepassword",
                  "excludeclipboardcontentfrommonitorprocessing", "clipboard viewer ignore", "cancloudsyncclipboard")
MAX_BYTES = 160 * 1024 * 1024


def marked_private(types):
    return any(marker in str(kind).lower() for kind in types for marker in SECRET_MARKERS)


def clipboard_allowed(board=None):
    board = board or AppKit.NSPasteboard.generalPasteboard()
    # Newer macOS exposes per-application access. Never generate repeated prompts
    # from the polling timer; an explicit setup button performs the initial read.
    if hasattr(board, "accessBehavior"):
        return int(board.accessBehavior()) == int(getattr(AppKit, "NSPasteboardAccessBehaviorAlwaysAllow", 2))
    return True


def request_clipboard():
    board = AppKit.NSPasteboard.generalPasteboard()
    board.stringForType_(AppKit.NSPasteboardTypeString)


def safe_snapshot(board, preserve=False):
    if not clipboard_allowed(board):
        return None
    sequence = int(board.changeCount())
    types = list(board.types() or [])
    if marked_private(types):
        return None
    records, total = [], 0
    items = [(item, list(item.types() or [])) for item in board.pasteboardItems() or []]
    if any(marked_private(kinds) for _, kinds in items):
        return None
    for item, kinds in items:
        for kind in kinds:
            if "canincludeinclipboardhistory" in str(kind).lower():
                permission = item.dataForType_(kind)
                if permission is None or bytes(permission) != b"\x01\x00\x00\x00":
                    return None
    for item, kinds in items:
        values = {}
        for kind in kinds:
            if not preserve and str(kind) not in (
                    "public.utf8-plain-text", "public.png", "public.tiff", "public.file-url"):
                continue
            data = item.dataForType_(kind)
            if data is None:
                if preserve:
                    return None  # promised/unreadable data cannot be safely restored
                continue
            total += len(data)
            if total > MAX_BYTES:
                return None
            values[str(kind)] = bytes(data)
        records.append(values)
    return (records, sequence) if int(board.changeCount()) == sequence else None


def snapshot_mime(snapshot):
    md = QMimeData()
    if snapshot is None:
        return md
    records, _ = snapshot
    urls = []
    for record in records:
        for kind, data in record.items():
            if kind == "public.utf8-plain-text":
                md.setText(data.decode("utf-8", errors="replace"))
            elif kind == "public.file-url":
                url = QUrl(data.decode("utf-8", errors="replace"))
                if url.isLocalFile() and not url.host():
                    urls.append(url)
            elif kind in ("public.png", "public.tiff"):
                buffer = QBuffer()
                buffer.setData(QByteArray(data))
                buffer.open(QIODevice.ReadOnly)
                reader = QImageReader(buffer)
                size = reader.size()
                if size.isValid() and size.width() * size.height() <= 40_000_000:
                    img = reader.read()
                    if not img.isNull():
                        md.setImageData(img)
    if urls:
        md.setUrls(urls)
    return md


class ClipboardSource(QObject):
    dataChanged = Signal()

    def __init__(self):
        super().__init__()
        self.board = AppKit.NSPasteboard.generalPasteboard()
        self.sequence = int(self.board.changeCount())
        self._mime = QMimeData()
        self.should_capture = lambda: True
        self.timer = QTimer(self)
        self.timer.timeout.connect(self._poll)
        self.timer.start(300)

    def _poll(self):
        current = int(self.board.changeCount())
        if current == self.sequence:
            return
        self.sequence = current
        if not self.should_capture() or not clipboard_allowed(self.board):
            self._mime = QMimeData()
            return
        try:
            self._mime = snapshot_mime(safe_snapshot(self.board))
            self.dataChanged.emit()
        finally:
            self._mime = QMimeData()  # no extra retained clipboard payload

    def mimeData(self):
        return self._mime

    def image(self):
        return self._mime.imageData()

    def text(self):
        return self._mime.text()

    def close(self):
        self.timer.stop()
        self._mime = QMimeData()


def _restore(board, previous, own_sequence):
    if int(board.changeCount()) != own_sequence:
        return False
    items = []
    for record in previous:
        item = AppKit.NSPasteboardItem.alloc().init()
        for kind, data in record.items():
            item.setData_forType_(data, kind)
        items.append(item)
    board.clearContents()
    return bool(board.writeObjects_(items)) if items else True


def paste_text(text, restore_clipboard=True, restore_delay=0.5, *, destination_check=None):
    def deliver():
        if not accessibility_allowed() or destination_check is None or not destination_check():
            return False
        board = AppKit.NSPasteboard.generalPasteboard()
        saved = safe_snapshot(board, preserve=True) if restore_clipboard else None
        if restore_clipboard and saved is None:
            return False
        # Do not release physical modifiers behind the user's back. If they are
        # still held, fail closed and leave the result available in history.
        flags = Quartz.CGEventSourceFlagsState(Quartz.kCGEventSourceStateCombinedSessionState)
        modifiers = (Quartz.kCGEventFlagMaskCommand | Quartz.kCGEventFlagMaskControl |
                     Quartz.kCGEventFlagMaskAlternate | Quartz.kCGEventFlagMaskShift)
        if flags & modifiers:
            return False
        board.clearContents()
        if not board.setString_forType_(text, AppKit.NSPasteboardTypeString):
            if saved:
                _restore(board, saved[0], int(board.changeCount()))
            return False
        sequence = int(board.changeCount())
        if not destination_check():
            if saved:
                _restore(board, saved[0], sequence)
            return False
        for down in (True, False):
            event = Quartz.CGEventCreateKeyboardEvent(None, 9, down)  # ANSI V
            Quartz.CGEventSetFlags(event, Quartz.kCGEventFlagMaskCommand)
            Quartz.CGEventPost(Quartz.kCGHIDEventTap, event)
        if saved:
            QTimer.singleShot(max(100, int(restore_delay * 1000)),
                              lambda: _restore(board, saved[0], sequence))
        return True
    return bool(on_main(deliver))
